{"content": "1|import {describe,it,expect,beforeEach,afterEach} from 'vitest';
2|import request from 'supertest';
3|import {mkdtemp,rm,readFile,writeFile} from 'node:fs/promises';
4|import os from 'node:os';
5|import path from 'node:path';
6|import {createApp} from '../server/app.js';
7|let dir,file,app;
8|const payload={title:'테스트 요청',description:'설명',requester:'요청자',assignee:'담당자',priority:'high'};
9|beforeEach(async()=>{dir=await mkdtemp(path.join(os.tmpdir(),'wrm-'));file=path.join(dir,'requests.json');app=createApp({dataFile:file});});
10|afterEach(async()=>{await rm(dir,{recursive:true,force:true});});
11|async function create(p=payload){return request(app).post('/api/requests').send(p);}
12|describe('고정 API 인수 테스트',()=>{
13| it('AC-001 생성과 UUID/기본 상태',async()=>{const r=await create();expect(r.status).toBe(201);expect(r.body.id).toMatch(/^[\da-f-]{36}$/);expect(r.body.status).toBe('received');expect(r.body.title).toBe(payload.title);expect(r.body.createdAt).toBeTruthy();});
14| it('AC-002 잘못된 입력은 400이고 저장되지 않는다',async()=>{for(const p of [{...payload,title:'  '},{...payload,priority:'urgent'},{title:'x'}]){expect((await create(p)).status).toBe(400);}expect((await request(app).get('/api/requests')).body.total).toBe(0);});
15| it('AC-003 상태+우선순위 AND 필터',async()=>{await create();await create({...payload,title:'두 번째',priority:'low'});const r=await request(app).get('/api/requests?status=received&priority=high');expect(r.status).toBe(200);expect(r.body.total).toBe(1);expect(r.body.items[0].priority).toBe('high');});
16| it('AC-004 상세와 미존재',async()=>{const r=await create();expect((await request(app).get(`/api/requests/${r.body.id}`)).status).toBe(200);expect((await request(app).get('/api/requests/00000000-0000-4000-8000-000000000000')).status).toBe(404);});
17| it('AC-005/006/007 상태 전이와 거부',async()=>{const r=await create();const url=`/api/requests/${r.body.id}/status`;expect((await request(app).patch(url).send({status:'completed'})).status).toBe(409);expect((await request(app).patch(url).send({status:'in_progress'})).status).toBe(200);expect((await request(app).patch(url).send({status:'completed'})).status).toBe(200);expect((await request(app).patch(url).send({status:'in_progress'})).status).toBe(200);});
18| it('AC-008 담당자와 우선순위 수정',async()=>{const r=await create();const u=await request(app).patch(`/api/requests/${r.body.id}`).send({assignee:'새 담당자',priority:'low'});expect(u.status).toBe(200);expect(u.body.assignee).toBe('새 담당자');expect(u.body.priority).toBe('low');expect(u.body.title).toBe(payload.title);});
19| it('AC-009 저장 후 앱 인스턴스 재생성',async()=>{const r=await create();const another=createApp({dataFile:file});expect((await request(another).get(`/api/requests/${r.body.id}`)).body.title).toBe(payload.title);});
20| it('AC-010 손상된 저장 파일은 500이며 보존',async()=>{await writeFile(file,'{invalid');expect((await request(app).get('/api/requests')).status).toBe(500);expect(await readFile(file,'utf8')).toBe('{invalid');});
21| it('AC-013 미허용 필드 거부',async()=>{expect((await create({...payload,status:'completed'})).status).toBe(400);});
22| it('AC-014 동일 값 수정 시 updatedAt 유지',async()=>{const r=await create();const u=await request(app).patch(`/api/requests/${r.body.id}`).send({priority:'high'});expect(u.body.updatedAt).toBe(r.body.updatedAt);const s=await request(app).patch(`/api/requests/${r.body.id}/status`).send({status:'received'});expect(s.body.updatedAt).toBe(r.body.updatedAt);});
23| it('잘못된 JSON과 필터는 400',async()=>{expect((await request(app).get('/api/requests?priority=urgent')).status).toBe(400);expect((await request(app).post('/api/requests').set('Content-Type','application/json').send('{oops')).status).toBe(400);});
24|});", "total_lines": 24, "file_size": 3867, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|import { describe, it, expect, beforeEach, afterEach } from 'vitest';
2|import request from 'supertest';
3|import { mkdtemp, rm, readFile } from 'node:fs/promises';
4|import os from 'node:os';
5|import path from 'node:path';
6|import { createApp } from '../server/app.js';
7|
8|let dir;
9|let file;
10|let app;
11|
12|const payload = {
13|  title: '계약 테스트 요청',
14|  description: '설명',
15|  requester: '요청자',
16|  assignee: '담당자',
17|  priority: 'high'
18|};
19|
20|beforeEach(async () => {
21|  dir = await mkdtemp(path.join(os.tmpdir(), 'wrm-contract-'));
22|  file = path.join(dir, 'requests.json');
23|  app = createApp({ dataFile: file });
24|});
25|
26|afterEach(async () => {
27|  await rm(dir, { recursive: true, force: true });
28|});
29|
30|const create = body => request(app).post('/api/requests').send(body);
31|
32|describe('추가 API 계약 인수 테스트', () => {
33|  it('AC-001 UUID v4, UTC 시각, 저장 후 재조회', async () => {
34|    const r = await create(payload);
35|    expect(r.status).toBe(201);
36|    expect(r.body.id).toMatch(
37|      /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
38|    );
39|    expect(r.body.createdAt).toMatch(/^\d{4}-\d{2}-\d{2}T.*Z$/);
40|    expect(r.body.updatedAt).toBe(r.body.createdAt);
41|
42|    const detail = await request(app).get(`/api/requests/${r.body.id}`);
43|    expect(detail.status).toBe(200);
44|    expect(detail.body).toEqual(r.body);
45|  });
46|
47|  it('AC-002 잘못된 값은 저장 데이터를 변경하지 않는다', async () => {
48|    const initial = await create(payload);
49|    expect(initial.status).toBe(201);
50|
51|    const original = await readFile(file, 'utf8');
52|
53|    const invalid = [
54|      { ...payload, title: '   ' },
55|      { ...payload, title: '가'.repeat(101) },
56|      { ...payload, requester: '가'.repeat(61) },
57|      { ...payload, assignee: '가'.repeat(61) },
58|      { ...payload, description: '가'.repeat(2001) },
59|      { ...payload, priority: 'urgent' }
60|    ];
61|
62|    for (const item of invalid) {
63|      const r = await create(item);
64|      expect(r.status).toBe(400);
65|      expect(r.body.error.code).toBe('VALIDATION_ERROR');
66|    }
67|
68|    expect(await readFile(file, 'utf8')).toBe(original);
69|  });
70|
71|  it('AC-004 존재하지 않는 요청은 NOT_FOUND', async () => {
72|    const r = await request(app).get(
73|      '/api/requests/00000000-0000-4000-8000-000000000000'
74|    );
75|    expect(r.status).toBe(404);
76|    expect(r.body.error.code).toBe('NOT_FOUND');
77|  });
78|
79|  it('AC-006 금지된 상태 전이는 저장 데이터를 변경하지 않는다', async () => {
80|    const created = await create(payload);
81|    const original = await readFile(file, 'utf8');
82|
83|    const r = await request(app)
84|      .patch(`/api/requests/${created.body.id}/status`)
85|      .send({ status: 'completed' });
86|
87|    expect(r.status).toBe(409);
88|    expect(r.body.error.code).toBe('INVALID_TRANSITION');
89|
90|    const detail = await request(app)
91|      .get(`/api/requests/${created.body.id}`);
92|
93|    expect(detail.body.status).toBe('received');
94|    expect(detail.body.updatedAt).toBe(created.body.updatedAt);
95|    expect(await readFile(file, 'utf8')).toBe(original);
96|  });
97|
98|  it('AC-008 수정 시 다른 필드는 유지된다', async () => {
99|    const created = await create(payload);
100|
101|    const r = await request(app)
102|      .patch(`/api/requests/${created.body.id}`)
103|      .send({ assignee: '변경 담당자', priority: 'low' });
104|
105|    expect(r.status).toBe(200);
106|    expect(r.body.assignee).toBe('변경 담당자');
107|    expect(r.body.priority).toBe('low');
108|    expect(r.body.title).toBe(created.body.title);
109|    expect(r.body.description).toBe(created.body.description);
110|    expect(r.body.requester).toBe(created.body.requester);
111|    expect(r.body.createdAt).toBe(created.body.createdAt);
112|    expect(Date.parse(r.body.updatedAt))
113|      .toBeGreaterThanOrEqual(Date.parse(created.body.updatedAt));
114|  });
115|
116|  it('AC-013 미허용 필드는 거부하고 저장을 변경하지 않는다', async () => {
117|    const created = await create(payload);
118|    const original = await readFile(file, 'utf8');
119|
120|    const r = await request(app)
121|      .patch(`/api/requests/${created.body.id}`)
122|      .send({ title: '무단 변경' });
