{"content": "1|// JSON 저장소: docs/specification.md "저장" (REQ-006)
2|// - 기본 ./data/requests.json, createApp({dataFile}) 옵션 우선
3|// - 파일 미존재 시 빈 배열 시작, 첫 쓰기 시 상위 디렉터리 안전 생성
4|// - 손상된 JSON은 초기화하지 않고 500 INTERNAL_ERROR
5|// - 같은 디렉터리의 고유 임시 파일에 쓰고 rename으로 원자적 교체
6|// - 읽기→수정→쓰기 전체를 직렬화 (순차 작업 큐)
7|
8|import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
9|import path from 'node:path';
10|import { internalError } from './errors.js';
11|
12|export const DEFAULT_DATA_FILE = './data/requests.json';
13|
14|export function createStore({ dataFile } = {}) {
15|  const file = path.resolve(dataFile ?? DEFAULT_DATA_FILE);
16|  const dir = path.dirname(file);
17|
18|  // 읽기→수정→쓰기 전체를 직렬화하는 순차 작업 큐.
19|  // 쓰기만 직렬화하면 두 요청이 같은 스냅샷을 읽어 한쪽 변경이 유실되므로
20|  // load부터 mutate, save까지 큐에서 순차 실행한다.
21|  let queue = Promise.resolve();
22|
23|  function enqueue(task) {
24|    const run = queue.then(task, task);
25|    // 큐 체인이 깨지지 않도록 실패를 흡수한다 (개별 작업의 결과는 그대로 반환).
26|    queue = run.then(() => undefined, () => undefined);
27|    return run;
28|  }
29|
30|  async function load() {
31|    let raw;
32|    try {
33|      raw = await readFile(file, 'utf8');
34|    } catch (err) {
35|      if (err && err.code === 'ENOENT') {
36|        return []; // 파일 미존재: 빈 배열 시작
37|      }
38|      // 파일이 있지만 읽기 실패 (권한 등): 조용히 초기화하지 않는다.
39|      throw internalError('저장 파일을 읽을 수 없습니다.');
40|    }
41|    try {
42|      const parsed = JSON.parse(raw);
43|      if (!Array.isArray(parsed)) {
44|        throw internalError('저장 파일 형식이 올바르지 않습니다.');
45|      }
46|      return parsed;
47|    } catch (err) {
48|      if (err instanceof Error && err.code === 'INTERNAL_ERROR') throw err;
49|      // 손상된 JSON: 빈 배열로 덮지 않고 500 보고.
50|      throw internalError('저장 파일이 손상되었습니다.');
51|    }
52|  }
53|
54|  async function save(items) {
55|    // 상위 디렉터리 안전 생성 (첫 쓰기 시)
56|    await mkdir(dir, { recursive: true });
57|    // 같은 디렉터리의 고유한 임시 파일에 쓰고 rename으로 원자적 교체
58|    const tmp = path.join(dir, `.${path.basename(file)}.${process.pid}.${Date.now()}.${Math.random().toString(36).slice(2)}.tmp`);
59|    await writeFile(tmp, JSON.stringify(items, null, 2), 'utf8');
60|    await rename(tmp, file);
61|  }
62|
63|  return {
64|    // 읽기 전용: 손상 파일이면 500 (AC-010). 파일을 덮지 않는다.
65|    load,
66|
67|    // 읽기→수정→쓰기 전체 직렬화. mutate(items)는 배열을 받아 새 배열을 반환.
68|    // 예외 발생 시 저장하지 않고 오류를 그대로 전파한다.
69|    mutate(fn) {
70|      return enqueue(async () => {
71|        const items = await load();
72|        const next = await fn(items);
73|        await save(next);
74|        return next;
75|      });
76|    },
77|
78|    // 읽기 전용 조회도 큐에 넣어 쓰기와의 순서를 보장한다.
79|    read() {
80|      return enqueue(async () => load());
81|    },
82|
83|    // 경로·파일명 노출 없이 저장소가 같은 파일을 가리키는지 비교 (차후 PATCH 재사용)
84|    file,
85|  };
86|}", "total_lines": 86, "file_size": 3380, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// 오류 형식과 코드: docs/specification.md "API 오류" (REQ-007)
2|// 형식: { "error": { "code": "...", "message": "..." } }
3|// 코드 4종: VALIDATION_ERROR, NOT_FOUND, INVALID_TRANSITION, INTERNAL_ERROR
4|// 스택 추적·서버 파일 경로는 노출하지 않는다.
5|
6|export const CODES = {
7|  VALIDATION_ERROR: 'VALIDATION_ERROR',
8|  NOT_FOUND: 'NOT_FOUND',
9|  INVALID_TRANSITION: 'INVALID_TRANSITION',
10|  INTERNAL_ERROR: 'INTERNAL_ERROR',
11|};
12|
13|export const STATUS_BY_CODE = {
14|  VALIDATION_ERROR: 400,
15|  NOT_FOUND: 404,
16|  INVALID_TRANSITION: 409,
17|  INTERNAL_ERROR: 500,
18|};
19|
20|export class ApiError extends Error {
21|  constructor(code, message, status) {
22|    super(message);
23|    this.name = 'ApiError';
24|    this.code = code;
25|    this.status = status ?? STATUS_BY_CODE[code] ?? 500;
26|  }
27|}
28|
29|export function validationError(message) {
30|  return new ApiError(CODES.VALIDATION_ERROR, message);
31|}
32|
33|export function notFoundError(message) {
34|  return new ApiError(CODES.NOT_FOUND, message);
35|}
36|
37|export function invalidTransitionError(message) {
38|  return new ApiError(CODES.INVALID_TRANSITION, message);
39|}
40|
41|export function internalError(message) {
42|  return new ApiError(CODES.INTERNAL_ERROR, message);
43|}
44|
45|// 중앙 오류 핸들러에서 사용: 오류를 {error:{code,message}}로 변환.
46|// 스택·경로 노출 없음. 알 수 없는 오류는 INTERNAL_ERROR로 통일.
47|export function toErrorResponse(err) {
48|  if (err instanceof ApiError) {
49|    return { status: err.status, body: { error: { code: err.code, message: err.message } } };
50|  }
51|  return {
52|    status: 500,
53|    body: { error: { code: CODES.INTERNAL_ERROR, message: '서버 내부 오류가 발생했습니다.' } },
54|  };
55|}", "total_lines": 55, "file_size": 1680, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// 유효성 검증: docs/specification.md "데이터 필드"·"생성" (REQ-001/007)
2|// - trim 후 Unicode 코드 포인트 기준 길이 (title 1-100, requester/assignee 1-60,
3|//   description 0-2000)
4|// - priority enum low/medium/high
5|// - 알 수 없는 필드·클라이언트 전달 id/status/시각 → 400
6|// - ID UUID v4 형식 검사 (승인 기준 C: 형식 검사를 조회보다 먼저 적용)
7|
8|import { validationError } from './errors.js';
9|
10|export const PRIORITIES = ['low', 'medium', 'high'];
11|export const STATUSES = ['received', 'in_progress', 'completed'];
12|
13|// UUID v4 (형식 유효성만; 어떤 버전 비트든 v4 패턴으로 검사)
14|const UUID_V4_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
15|
16|export function isUuidV4(value) {
17|  return typeof value === 'string' && UUID_V4_RE.test(value);
18|}
19|
20|// 코드 포인트 기준 길이 (String.prototype.length는 UTF-16 코드 단위 기준이므로
21|// 서로게이트 쌍 2칸 문제를 피하려고 Array.from으로 코드 포인트를 센다)
22|export function codePointLength(value) {
23|  return Array.from(value).length;
24|}
25|
26|function requireString(value, field) {
27|  if (typeof value !== 'string') {
28|    throw validationError(`${field} 필드는 문자열이어야 합니다.`);
29|  }
30|  return value.trim();
31|}
32|
33|function requireLength(value, field, min, max) {
34|  const trimmed = requireString(value, field);
35|  const len = codePointLength(trimmed);
36|  if (len < min || len > max) {
37|    throw validationError(`${field} 필드는 ${min}~${max}자(코드 포인트)여야 합니다.`);
38|  }
39|  return trimmed;
40|}
41|
42|function requireEnum(value, field, allowed) {
43|  if (typeof value !== 'string' || !allowed.includes(value)) {
44|    throw validationError(`${field} 필드는 ${allowed.join(', ')} 중 하나여야 합니다.`);
45|  }
46|  return value;
47|}
48|
49|// POST /api/requests 본문 검증. 성공 시 정규화된 생성 입력을 반환.
50|// 허용 필드: title, description, requester, assignee, priority.
51|// 알 수 없는 필드(id/status/createdAt/updatedAt 등)는 400.
52|export function validateCreate(body) {
53|  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
54|    throw validationError('요청 본문은 JSON 객체여야 합니다.');
55|  }
56|  const allowed = ['title', 'description', 'requester', 'assignee', 'priority'];
57|  const unknown = Object.keys(body).filter((k) => !allowed.includes(k));
58|  if (unknown.length > 0) {
59|    throw validationError(`허용되지 않는 필드가 있습니다: ${unknown.join(', ')}`);
60|  }
61|  for (const field of ['title', 'requester', 'assignee', 'priority']) {
62|    if (!(field in body)) {
63|      throw validationError(`${field} 필드는 필수입니다.`);
64|    }
65|  }
66|  const title = requireLength(body.title, 'title', 1, 100);
67|  const requester = requireLength(body.requester, 'requester', 1, 60);
68|  const assignee = requireLength(body.assignee, 'assignee', 1, 60);
69|  const priority = requireEnum(body.priority, 'priority', PRIORITIES);
70|  let description = '';
71|  if (body.description !== undefined) {
72|    if (body.description === null) {
73|      throw validationError('description 필드는 문자열이어야 합니다.');
74|    }
75|    description = requireLength(body.description, 'description', 0, 2000);
76|  }
77|  return { title, description, requester, assignee, priority };
78|}
79|
80|// 목록 필터 검증: status/priority는 선택적이며, 지정 시 enum이어야 한다.
81|export function validateListFilters(query) {
82|  const filters = {};
83|  if (query.status !== undefined) {
84|    filters.status = requireEnum(query.status, 'status', STATUSES);
85|  }
86|  if (query.priority !== undefined) {
87|    filters.priority = requireEnum(query.priority, 'priority', PRIORITIES);
88|  }
89|  return filters;
90|}
91|
92|// 경로 ID 검증 (승인 기준 C): 형식 오류 → 400 VALIDATION_ERROR.
93|export function validateId(id) {
94|  if (!isUuidV4(id)) {
95|    throw validationError('요청 ID는 UUID v4 형식이어야 합니다.');
96|  }
97|  return id;
98|}", "total_lines": 98, "file_size": 3955, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

