{"content": "1|// API 클라이언트: Vite 프록시(/api → http://localhost:3001)를 사용하는 상대 경로
2|// 오류 형식 {error:{code,message}} 파싱 (REQ-007)
3|import type { ApiErrorBody, CreateRequestInput, ListFilters, WorkRequest, WorkRequestList } from './types';
4|import { isApiErrorBody } from './types';
5|
6|export class ApiError extends Error {
7|  readonly status: number;
8|  readonly code: string;
9|  constructor(status: number, code: string, message: string) {
10|    super(message);
11|    this.name = 'ApiError';
12|    this.status = status;
13|    this.code = code;
14|  }
15|}
16|
17|async function request<T>(url: string, init?: RequestInit): Promise<T> {
18|  let response: Response;
19|  try {
20|    response = await fetch(url, init);
21|  } catch {
22|    // 네트워크 오류 (fetch 실패): 오류 본문 없음
23|    throw new ApiError(0, 'NETWORK_ERROR', '서버에 연결할 수 없습니다.');
24|  }
25|  const text = await response.text();
26|  let body: unknown = undefined;
27|  if (text.length > 0) {
28|    try {
29|      body = JSON.parse(text);
30|    } catch {
31|      body = undefined;
32|    }
33|  }
34|  if (!response.ok) {
35|    if (isApiErrorBody(body)) {
36|      throw new ApiError(response.status, body.error.code, body.error.message);
37|    }
38|    throw new ApiError(response.status, 'INTERNAL_ERROR', '서버 오류가 발생했습니다.');
39|  }
40|  return body as T;
41|}
42|
43|export function listRequests(filters: ListFilters = {}): Promise<WorkRequestList> {
44|  const params = new URLSearchParams();
45|  if (filters.status !== undefined) params.set('status', filters.status);
46|  if (filters.priority !== undefined) params.set('priority', filters.priority);
47|  const query = params.toString();
48|  return request<WorkRequestList>(`/api/requests${query ? `?${query}` : ''}`);
49|}
50|
51|export function getRequest(id: string): Promise<WorkRequest> {
52|  return request<WorkRequest>(`/api/requests/${encodeURIComponent(id)}`);
53|}
54|
55|export function createRequest(input: CreateRequestInput): Promise<WorkRequest> {
56|  return request<WorkRequest>('/api/requests', {
57|    method: 'POST',
58|    headers: { 'Content-Type': 'application/json' },
59|    body: JSON.stringify(input),
60|  });
61|}", "total_lines": 61, "file_size": 2106, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

