{"content": "1|// 앱 라우팅: 라우터 라이브러리 없이 해시 기반 화면 전환
2|// - '#/' → WF-01 목록, '#/new' → WF-02 등록, '#/requests/:id' → WF-03 상세
3|// - PATCH 수정과 상태 변경은 다음 교시 범위이므로 상세 화면에 미구현 기능을
4|//   작동하는 것처럼 표현하지 않는다.
5|import { useCallback, useEffect, useState } from 'react';
6|import { RequestList } from './components/RequestList';
7|import { RequestForm } from './components/RequestForm';
8|import { RequestDetail } from './components/RequestDetail';
9|
10|type Route =
11|  | { name: 'list' }
12|  | { name: 'new' }
13|  | { name: 'detail'; id: string };
14|
15|function parseHash(hash: string): Route {
16|  const path = hash.replace(/^#/, '');
17|  if (path === '/new') return { name: 'new' };
18|  const match = path.match(/^\/requests\/([^/]+)$/);
19|  if (match) return { name: 'detail', id: decodeURIComponent(match[1]) };
20|  return { name: 'list' };
21|}
22|
23|export function App() {
24|  const [route, setRoute] = useState<Route>(() => parseHash(window.location.hash));
25|
26|  useEffect(() => {
27|    const onHashChange = () => {
28|      setRoute(parseHash(window.location.hash));
29|    };
30|    window.addEventListener('hashchange', onHashChange);
31|    return () => {
32|      window.removeEventListener('hashchange', onHashChange);
33|    };
34|  }, []);
35|
36|  const navigate = useCallback((hash: string) => {
37|    window.location.hash = hash;
38|  }, []);
39|
40|  return (
41|    <div className="app">
42|      <header className="app-header">
43|        <h1>AI Work Request Manager 2.0</h1>
44|        {route.name === 'list' && (
45|          <div className="app-header__actions">
46|            <button
47|              type="button"
48|              className="btn btn--primary"
49|              onClick={() => navigate('#/new')}
50|            >
51|              요청 등록
52|            </button>
53|          </div>
54|        )}
55|      </header>
56|      {route.name === 'list' && <RequestList onNavigate={navigate} />}
57|      {route.name === 'new' && <RequestForm onNavigate={navigate} />}
58|      {route.name === 'detail' && <RequestDetail id={route.id} onNavigate={navigate} />}
59|    </div>
60|  );
61|}", "total_lines": 61, "file_size": 2099, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// WF-01 목록 화면: GET /api/requests, 상태·우선순위 필터 동시 적용(AND),
2|// total = 필터 후 개수(기준 A), 로딩·빈 목록·오류·재시도 구분,
3|// 제목 클릭 → 상세, 모바일 카드 목록(동일 정보·조작).
4|import { useCallback, useEffect, useState } from 'react';
5|import { ApiError, listRequests } from '../api';
6|import { PRIORITY_LABEL, PRIORITY_OPTIONS, STATUS_LABEL, STATUS_OPTIONS, formatDateTime } from '../labels';
7|import type { ListFilters, WorkRequest } from '../types';
8|
9|type LoadState =
10|  | { kind: 'loading' }
11|  | { kind: 'error'; message: string }
12|  | { kind: 'loaded'; items: WorkRequest[]; total: number };
13|
14|function statusBadge(status: WorkRequest['status']) {
15|  return <span className={`badge badge--${status}`}>{STATUS_LABEL[status]}</span>;
16|}
17|
18|function priorityBadge(priority: WorkRequest['priority']) {
19|  return <span className={`badge badge--priority-${priority}`}>{PRIORITY_LABEL[priority]}</span>;
20|}
21|
22|function RequestTitleLink({ request, onNavigate }: { request: WorkRequest; onNavigate: (hash: string) => void }) {
23|  return (
24|    <button
25|      type="button"
26|      className="request-title-link"
27|      onClick={() => onNavigate(`#/requests/${encodeURIComponent(request.id)}`)}
28|    >
29|      {request.title}
30|    </button>
31|  );
32|}
33|
34|interface Props {
35|  onNavigate: (hash: string) => void;
36|}
37|
38|export function RequestList({ onNavigate }: Props) {
39|  const [filters, setFilters] = useState<ListFilters>({});
40|  const [state, setState] = useState<LoadState>({ kind: 'loading' });
41|  const [reloadKey, setReloadKey] = useState(0);
42|
43|  useEffect(() => {
44|    let cancelled = false;
45|    setState({ kind: 'loading' });
46|    listRequests(filters)
47|      .then((result) => {
48|        if (!cancelled) setState({ kind: 'loaded', items: result.items, total: result.total });
49|      })
50|      .catch((error: unknown) => {
51|        if (!cancelled) {
52|          const message = error instanceof ApiError ? error.message : '요청을 불러오는 중 오류가 발생했습니다.';
53|          setState({ kind: 'error', message });
54|        }
55|      });
56|    return () => {
57|      cancelled = true;
58|    };
59|  }, [filters, reloadKey]);
60|
61|  const onFilterChange = useCallback((next: ListFilters) => {
62|    setFilters(next);
63|  }, []);
64|
65|  const onRetry = useCallback(() => {
66|    setReloadKey((key) => key + 1);
67|  }, []);
68|
69|  return (
70|    <section aria-label="요청 목록">
71|      <div className="filter-bar">
72|        <label htmlFor="filter-status">
73|          상태
74|          <select
75|            id="filter-status"
76|            value={filters.status ?? ''}
77|            onChange={(event) => {
78|              const value = event.target.value;
79|              onFilterChange({ ...filters, status: value === '' ? undefined : (value as ListFilters['status']) });
80|            }}
81|          >
82|            <option value="">전체</option>
83|            {STATUS_OPTIONS.map((status) => (
84|              <option key={status} value={status}>
85|                {STATUS_LABEL[status]}
86|              </option>
87|            ))}
88|          </select>
89|        </label>
90|        <label htmlFor="filter-priority">
91|          우선순위
92|          <select
93|            id="filter-priority"
94|            value={filters.priority ?? ''}
95|            onChange={(event) => {
96|              const value = event.target.value;
97|              onFilterChange({ ...filters, priority: value === '' ? undefined : (value as ListFilters['priority']) });
98|            }}
99|          >
100|            <option value="">전체</option>
101|            {PRIORITY_OPTIONS.map((priority) => (
102|              <option key={priority} value={priority}>
103|                {PRIORITY_LABEL[priority]}
104|              </option>
105|            ))}
106|          </select>
107|        </label>
108|        <span className="filter-bar__total">총 {state.kind === 'loaded' ? state.total : 0}건</span>
109|      </div>
110|
111|      {state.kind === 'loading' && (
112|        <div className="state" role="status">로딩 중…</div>
113|      )}
114|
115|      {state.kind === 'error' && (
116|        <div className="state state--error" role="alert">
117|          <p>요청 목록을 불러오지 못했습니다. {state.message}</p>
118|          <button type="button" className="btn" onClick={onRetry}>재시도</button>
119|        </div>
120|      )}
121|
122|      {state.kind === 'loaded' && state.items.length === 0 && (
123|        <div className="state" role="status">결과 없음</div>
124|      )}
125|
126|      {state.kind === 'loaded' && state.items.length > 0 && (
127|        <>
128|          <div className="table-wrap">
129|            <table>
130|              <thead>
131|                <tr>
132|                  <th scope="col">ID</th>
133|                  <th scope="col">제목</th>
134|                  <th scope="col">상태</th>
135|                  <th scope="col">우선순위</th>
136|                  <th scope="col">담당자</th>
137|                  <th scope="col">생성 시각</th>
138|                </tr>
139|              </thead>
140|              <tbody>
141|                {state.items.map((request) => (
142|                  <tr key={request.id}>
143|                    <td>{request.id}</td>
144|                    <td>
145|                      <RequestTitleLink request={request} onNavigate={onNavigate} />
146|                    </td>
147|                    <td>{statusBadge(request.status)}</td>
148|                    <td>{priorityBadge(request.priority)}</td>
149|                    <td>{request.assignee}</td>
150|                    <td>{formatDateTime(request.createdAt)}</td>
151|                  </tr>
152|                ))}
153|              </tbody>
154|            </table>
155|          </div>
156|
157|          <div className="card-list">
158|            {state.items.map((request) => (
159|              <div className="card" key={request.id}>
160|                <RequestTitleLink request={request} onNavigate={onNavigate} />
161|                <dl>
162|                  <dt>ID</dt>
163|                  <dd>{request.id}</dd>
164|                  <dt>상태</dt>
165|                  <dd>{statusBadge(request.status)}</dd>
166|                  <dt>우선순위</dt>
167|                  <dd>{priorityBadge(request.priority)}</dd>
168|                  <dt>담당자</dt>
169|                  <dd>{request.assignee}</dd>
170|                  <dt>생성 시각</dt>
171|                  <dd>{formatDateTime(request.createdAt)}</dd>
172|                </dl>
173|              </div>
174|            ))}
175|          </div>
176|        </>
177|      )}
178|    </section>
179|  );
