{"content": "1|// WF-02 요청 등록 화면: POST /api/requests
2|// - 제목 input id=f-title name=title, 설명 textarea id=f-description name=description,
3|//   요청자 input id=f-requester name=requester, 담당자 input id=f-assignee name=assignee
4|// - 우선순위 radio 3개 name=priority, 한국어 라벨
5|// - 제출 버튼 type=submit, 접근 가능한 이름에 '등록' 포함
6|// - 계약 검증: 필수·문자 길이(코드 포인트)·공백 trim, 오류는 필드에 연결
7|// - 제출 중 재클릭·Enter 중복 제출 방지, 오류 시 입력 유지
8|// - 201 성공 시 요청 상세 화면으로 이동
9|import { useCallback, useState } from 'react';
10|import { ApiError, createRequest } from '../api';
11|import { PRIORITY_LABEL, PRIORITY_OPTIONS } from '../labels';
12|import type { CreateRequestInput, Priority } from '../types';
13|
14|type FieldName = 'title' | 'description' | 'requester' | 'assignee' | 'priority';
15|
16|interface FormValues {
17|  title: string;
18|  description: string;
19|  requester: string;
20|  assignee: string;
21|  priority: Priority;
22|}
23|
24|const INITIAL_VALUES: FormValues = {
25|  title: '',
26|  description: '',
27|  requester: '',
28|  assignee: '',
29|  priority: 'medium',
30|};
31|
32|// 코드 포인트 기준 길이 (서버와 동일: UTF-16 코드 단위가 아닌 코드 포인트)
33|function codePointLength(value: string): number {
34|  return Array.from(value).length;
35|}
36|
37|// 계약 검증 (schemas/request.schema.json, docs/specification.md "생성"):
38|// title 1~100, requester/assignee 1~60, description 0~2000, priority enum.
39|// trim 후 길이 검사. 오류는 필드별로 반환.
40|function validate(values: FormValues): Partial<Record<FieldName, string>> {
41|  const errors: Partial<Record<FieldName, string>> = {};
42|  const title = values.title.trim();
43|  if (title.length === 0) {
44|    errors.title = '제목은 필수입니다.';
45|  } else if (codePointLength(title) > 100) {
46|    errors.title = '제목은 100자(코드 포인트) 이내여야 합니다.';
47|  }
48|  const description = values.description.trim();
49|  if (codePointLength(description) > 2000) {
50|    errors.description = '설명은 2000자(코드 포인트) 이내여야 합니다.';
51|  }
52|  const requester = values.requester.trim();
53|  if (requester.length === 0) {
54|    errors.requester = '요청자는 필수입니다.';
55|  } else if (codePointLength(requester) > 60) {
