{"content": "1|// WF-03 상세 화면: GET /api/requests/{id}
2|// - 제목 heading의 접근 가능한 이름은 '요청 상세'
3|// - 제목·설명·요청자·담당자·우선순위·상태·생성/수정 시각 표시
4|// - 로딩·404·네트워크 오류를 구분하고 목록으로 돌아가는 버튼 제공
5|// - PATCH 수정과 상태 변경은 다음 교시 범위: 작동하는 것처럼 표현하지 않는다.
6|import { useCallback, useEffect, useState } from 'react';
7|import { ApiError, getRequest } from '../api';
8|import { PRIORITY_LABEL, STATUS_LABEL, formatDateTime } from '../labels';
9|import type { WorkRequest } from '../types';
10|
11|type LoadState =
12|  | { kind: 'loading' }
13|  | { kind: 'not-found' }
14|  | { kind: 'error'; message: string }
15|  | { kind: 'loaded'; request: WorkRequest };
16|
17|interface Props {
18|  id: string;
19|  onNavigate: (hash: string) => void;
20|}
21|
22|export function RequestDetail({ id, onNavigate }: Props) {
23|  const [state, setState] = useState<LoadState>({ kind: 'loading' });
24|  const [reloadKey, setReloadKey] = useState(0);
25|
26|  useEffect(() => {
27|    let cancelled = false;
28|    setState({ kind: 'loading' });
29|    getRequest(id)
30|      .then((request) => {
31|        if (!cancelled) setState({ kind: 'loaded', request });
32|      })
33|      .catch((error: unknown) => {
34|        if (!cancelled) {
35|          if (error instanceof ApiError && error.status === 404) {
36|            setState({ kind: 'not-found' });
37|          } else {
38|            const message = error instanceof ApiError ? error.message : '요청을 불러오는 중 오류가 발생했습니다.';
39|            setState({ kind: 'error', message });
40|          }
41|        }
42|      });
43|    return () => {
44|      cancelled = true;
45|    };
46|  }, [id, reloadKey]);
47|
48|  const onRetry = useCallback(() => {
49|    setReloadKey((key) => key + 1);
50|  }, []);
51|
52|  return (
53|    <section aria-label="요청 상세">
54|      <p>
55|        <button type="button" className="btn" onClick={() => onNavigate('#/')}>
56|          목록으로
57|        </button>
58|      </p>
59|
60|      {state.kind === 'loading' && (
61|        <div className="state" role="status">로딩 중…</div>
62|      )}
63|
64|      {state.kind === 'not-found' && (
65|        <div className="state state--error" role="alert">
66|          <p>요청을 찾을 수 없습니다.</p>
67|          <button type="button" className="btn" onClick={onRetry}>재시도</button>
68|        </div>
69|      )}
70|
71|      {state.kind === 'error' && (
72|        <div className="state state--error" role="alert">
73|          <p>요청을 불러오지 못했습니다. {state.message}</p>
74|          <button type="button" className="btn" onClick={onRetry}>재시도</button>
75|        </div>
76|      )}
77|
78|      {state.kind === 'loaded' && (
79|        <div className="detail">
80|          <h2 className="detail__heading">요청 상세</h2>
81|          <div className="detail__section">
82|            <dl>
83|              <dt>제목</dt>
84|              <dd>{state.request.title}</dd>
85|              <dt>설명</dt>
86|              <dd>{state.request.description}</dd>
87|              <dt>요청자</dt>
88|              <dd>{state.request.requester}</dd>
89|              <dt>담당자</dt>
90|              <dd>{state.request.assignee}</dd>
91|              <dt>우선순위</dt>
92|              <dd>{PRIORITY_LABEL[state.request.priority]}</dd>
93|              <dt>상태</dt>
94|              <dd>{STATUS_LABEL[state.request.status]}</dd>
95|              <dt>생성 시각</dt>
96|              <dd>{formatDateTime(state.request.createdAt)}</dd>
97|              <dt>수정 시각</dt>
98|              <dd>{formatDateTime(state.request.updatedAt)}</dd>
99|            </dl>
100|          </div>
101|          {/* PATCH 수정과 상태 변경은 다음 교시 범위이므로 이 화면에서
102|              작동하는 것처럼 표현하지 않는다. */}
103|        </div>
104|      )}
105|    </section>
106|  );
