{"content": "1|// 라우트: REQ-001 (등록), REQ-002 (목록·필터), REQ-003 (상세)
2|// 이번 교시 범위: POST /api/requests, GET /api/requests, GET /api/requests/:id
3|// 다음 교시 범위: PATCH /api/requests/:id, PATCH /api/requests/:id/status (REQ-004/005)
4|
5|import { randomUUID } from 'node:crypto';
6|import { notFoundError } from './errors.js';
7|import { validateCreate, validateListFilters, validateId } from './validate.js';
8|
9|// GET /api/requests 응답: {items, total}. total = 필터 적용 후 items.length (기준 A).
10|// 정렬: createdAt 내림차순, 동률이면 id 오름차순.
11|function sortItems(items) {
12|  return [...items].sort((a, b) => {
13|    if (a.createdAt !== b.createdAt) {
14|      return a.createdAt < b.createdAt ? 1 : -1;
15|    }
16|    return a.id < b.id ? -1 : 1;
17|  });
18|}
19|
20|function applyFilters(items, filters) {
21|  return items.filter((item) => {
22|    if (filters.status !== undefined && item.status !== filters.status) return false;
23|    if (filters.priority !== undefined && item.priority !== filters.priority) return false;
24|    return true;
25|  });
26|}
27|
28|export function registerRoutes(app, store) {
29|  // REQ-001 등록
30|  app.post('/api/requests', async (req, res, next) => {
31|    try {
32|      const input = validateCreate(req.body);
33|      const now = new Date().toISOString();
34|      const item = {
35|        id: randomUUID(),
36|        title: input.title,
37|        description: input.description,
38|        requester: input.requester,
39|        assignee: input.assignee,
40|        priority: input.priority,
41|        status: 'received',
42|        createdAt: now,
43|        updatedAt: now,
44|      };
45|      const items = await store.mutate((current) => [...current, item]);
46|      const saved = items.find((it) => it.id === item.id);
47|      res.status(201).json(saved ?? item);
48|    } catch (err) {
49|      next(err);
50|    }
51|  });
52|
53|  // REQ-002 목록·필터
54|  app.get('/api/requests', async (req, res, next) => {
55|    try {
56|      const filters = validateListFilters(req.query);
57|      const items = await store.read();
58|      const filtered = sortItems(applyFilters(items, filters));
59|      res.status(200).json({ items: filtered, total: filtered.length });
60|    } catch (err) {
61|      next(err);
62|    }
63|  });
64|
65|  // REQ-003 상세 (기준 C: UUID 형식 검사를 조회보다 먼저)
66|  app.get('/api/requests/:id', async (req, res, next) => {
67|    try {
68|      const id = validateId(req.params.id);
69|      const items = await store.read();
70|      const item = items.find((it) => it.id === id);
71|      if (!item) {
72|        throw notFoundError('요청을 찾을 수 없습니다.');
73|      }
74|      res.status(200).json(item);
75|    } catch (err) {
76|      next(err);
77|    }
78|  });
79|
80|  // 다음 교시 범위: PATCH /api/requests/:id, PATCH /api/requests/:id/status
81|  // 여기에는 구현하지 않는다. 미구현 경로는 Express 기본 404를 거친다.
82|}", "total_lines": 82, "file_size": 2828, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

